import { createClient } from '@supabase/supabase-js';
import { S3Client, CopyObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3';

const sb = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
const r2 = new S3Client({
  region: "auto",
  endpoint: `https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`,
  credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID!, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY! },
});
const bucket = process.env.R2_BUCKET_NAME ?? "kakomon";

const university = process.argv[2];
const subject = process.argv[3];
const toVariant = process.argv[4];
const examType = process.argv[5] || null; // optional filter
const mode = process.argv[6]; // --dry-run or --force

if (!university || !subject || !toVariant || !mode) {
  console.error("Usage: npx tsx /tmp/rename-null-variant.ts <university> <subject> <toVariant> [examType] <--dry-run|--force>");
  process.exit(1);
}

async function main() {
  let q = sb.from("kakomon_documents")
    .select("id,year,exam_type,content_type,subject_variant,pdf_storage_path")
    .eq("university_id", university)
    .eq("subject", subject)
    .is("subject_variant", null)
    .order("year").order("content_type");
  if (examType && examType !== '--dry-run' && examType !== '--force') {
    q = q.eq("exam_type", examType);
  }
  const { data, error } = await q;
  if (error) { console.error(error); process.exit(1); }
  if (!data?.length) { console.log("No matching records."); return; }

  console.log(`Found ${data.length} NULL-variant records to rename → ${toVariant}:\n`);
  const ops = data.map(r => {
    // math/zenki/problem.pdf → math_econ_edu/zenki/problem.pdf
    const oldSeg = `${subject}/`;
    const newSeg = `${subject}_${toVariant}/`;
    const newPath = r.pdf_storage_path.replace(oldSeg, newSeg);
    console.log(`  ${r.year} ${r.exam_type} ${r.content_type} ${r.pdf_storage_path} → ${newPath}`);
    return { id: r.id, oldPath: r.pdf_storage_path, newPath };
  });

  if (mode === '--dry-run') { console.log("\n(dry-run)"); return; }

  console.log("\nR2 copy...");
  for (const op of ops) {
    await r2.send(new CopyObjectCommand({ Bucket: bucket, CopySource: `${bucket}/${op.oldPath}`, Key: op.newPath }));
    console.log(`  Copied: ${op.oldPath} → ${op.newPath}`);
  }
  console.log("DB update...");
  for (const op of ops) {
    const { error: ue } = await sb.from("kakomon_documents")
      .update({ subject_variant: toVariant, pdf_storage_path: op.newPath }).eq("id", op.id);
    if (ue) console.error(`  FAILED: ${op.id}: ${ue.message}`);
    else console.log(`  Updated: ${op.id.slice(0,8)}`);
  }
  console.log("R2 delete old...");
  for (const op of ops) {
    await r2.send(new DeleteObjectCommand({ Bucket: bucket, Key: op.oldPath }));
    console.log(`  Deleted: ${op.oldPath}`);
  }
  console.log("Done.");
}
main();
